<?php
$pageTitle='Game Details'; require_once 'config/bootstrap.php'; $id=(int)($_GET['id']??0);
$s=$pdo->prepare('SELECT g.* FROM games g WHERE g.id=?');$s->execute([$id]);$game=$s->fetch(); if(!$game){http_response_code(404);die('Game not found.');}
$offers=$pdo->prepare('SELECT * FROM store_offers WHERE game_id=? AND is_available=1 ORDER BY price ASC, store_name ASC');$offers->execute([$id]);$offers=$offers->fetchAll();$best=$offers[0]??null;
$user=current_user($pdo);$played=false;if($user){ensure_personalization_table($pdo);$ps=$pdo->prepare('SELECT 1 FROM played_games WHERE user_id=? AND game_id=?');$ps->execute([$user['id'],$id]);$played=(bool)$ps->fetchColumn();}$wishlist=false;if($user){$w=$pdo->prepare('SELECT 1 FROM wishlists WHERE user_id=? AND game_id=?');$w->execute([$user['id'],$id]);$wishlist=(bool)$w->fetchColumn();}
$local=game_rating($pdo,$id);$rating=(float)($game['store_rating']??0);$externalReviews=external_review_sources($game,$offers);$steamSnap=steam_snapshot($game);$trailerSearch=youtube_search_url($game['title']);
$reviewsStmt=$pdo->prepare('SELECT r.rating,r.review,r.created_at,u.name FROM ratings r JOIN users u ON u.id=r.user_id WHERE r.game_id=? ORDER BY r.created_at DESC');$reviewsStmt->execute([$id]);$reviews=$reviewsStmt->fetchAll();
$tags=game_tags($game['genres']);
$similarGames=[];
if($tags){
    $similar=$pdo->prepare('SELECT * FROM games WHERE id<>? AND ('.implode(' OR ',array_fill(0,count($tags),'genres LIKE ?')).') ORDER BY featured DESC, store_rating DESC, title ASC LIMIT 6');
    $simParams=[$id];
    foreach($tags as $tag)$simParams[]='%'.$tag.'%';
    $similar->execute($simParams);
    $similarGames=$similar->fetchAll();
}
require 'partials/header.php';
