r</span><strong id="gamePublisher"><?=e($game['publisher'])?></strong></div><div><span>Release</span><strong id="gameRelease"><?=e($game['release_date'])?></strong></div><div><span>Game mode</span><strong id="gameMode"><?=e($game['game_mode'])?></strong></div></div></div></div>
