<script>
(async function(){
  const id=<?=json_encode($id)?>;
  try{
    const r=await fetch('api/game-metadata.php?id='+encodeURIComponent(id),{headers:{'Accept':'application/json'}});
    const d=await r.json();
    if(!d.ok||!d.found)return;
    const set=(id,v)=>{const e=document.getElementById(id);if(e&&v)e.textContent=v;};
    if(d.cover_image){const img=document.getElementById('gameCover');if(img)img.src=d.cover_image;}
    set('gameDeveloper',d.developer);set('gamePublisher',d.publisher);set('gameRelease',d.release_date);set('gameMode',d.game_mode);
    const desc=document.getElementById('gameDescription');if(desc&&d.description)desc.textContent=d.description;
    const rating=document.getElementById('gameRating');if(rating&&d.rating!==null){rating.innerHTML='<span>⭐ '+Number(d.rating).toFixed(1)+'/100</span><span>'+Number(d.rating_count||0).toLocaleString('en-IN')+' Steam ratings</span>';}
  }catch(e){}
})();
</script>
